int checks=0;void Check(bool ok,string name){checks++;if(!ok)throw new Exception(name);}
string root=Path.Combine(Environment.GetEnvironmentVariable("LPLK_BUILD_ROOT")!,"AdministrationMaintenanceChecks","test-data");
T Field<T>(object p,string name)=>(T)p.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(p)!;
void Set(object p,string name,object value)=>p.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic)!.SetValue(p,value);
void Refresh(object p){if(p is LPLK_Teams.Plugin t){Set(p,"nextTick",0d);Set(p,"nextStatus",0d);t.Tick();}else{Set(p,"_lastConfigCheck",DateTimeOffset.MinValue);Set(p,"_nextScan",0L);((LPLK_ChatGuard.Plugin)p).Tick();}}
MenuWorld World(string id){var w=new MenuWorld{DataDirectory=Path.Combine(root,id)};Directory.CreateDirectory(w.DataDirectory);w.Permissions.Add("lplk.admin");return w;}
async Task Choose(MenuWorld world,string label){for(int i=0;i<300;i++){IMenuOption option;try{option=world.FindExact(label);}catch(InvalidOperationException){if(!world.Labels.Any(x=>x.Contains("Nächste")))throw;await world.Click("Nächste");continue;}await world.Click(option);return;}throw new Exception("Paging cycle");}
