var selections=new Dictionary<ulong,ulong>();for(ulong i=1;i<=7;i++)selections[76561198000000000+i]=76561198000000000;string selectionPath=Path.Combine(tw.DataDirectory,"selected-players.json");File.WriteAllText(selectionPath,JsonSerializer.Serialize(selections));string selectionBefore=File.ReadAllText(selectionPath);
