File.WriteAllText(tp,JsonSerializer.Serialize(ts with{Enabled=true,FallbackMaxRounds=333}));await Choose(tw,"Aktiv: False");Check(!Field<TeamSettings>(teams,"settings").Enabled&&Field<TeamSettings>(teams,"settings").FallbackMaxRounds==333,"Toggle uses unseen external value, preserves external settings");
await Choose(tw,"Zuschauer erlauben: True");Check(!Field<TeamSettings>(teams,"settings").AllowSpectator,"Paged rule accessible");
File.WriteAllText(tp,"{\"FallbackMaxRounds\":0}");await Choose(tw,"Autorunden: True");Check(Field<TeamSettings>(teams,"settings").AutoDetectMaxRounds&&File.ReadAllText(tp).Contains(":0"),"Invalid file not overwritten by menu");
File.WriteAllText(tp,JsonSerializer.Serialize(ts));Refresh(teams);var permit=Field<TeamPermits>(teams,"permits");var key=new ConnectionKey(1,tw.Player.SteamID,tw.Player.SessionId);permit.Grant(key,2,1);DateTime stamp=File.GetLastWriteTimeUtc(tp);File.WriteAllText(tp,JsonSerializer.Serialize(ts with{FallbackMaxRounds=98}));File.SetLastWriteTimeUtc(tp,stamp);Refresh(teams);Check(Field<TeamSettings>(teams,"settings").FallbackMaxRounds==98&&!permit.Consume(key,2,1.1),"Same timestamp reload invalidates old move permits");
teams.AdminCommand(tw.Context);await Choose(tw,"Ersatz-Rundenzahl: 98");var teamInput=(InputMenuOption)tw.Current!.Options[0];Check(!teamInput.SetValue(tw.Player,"1001")&&teamInput.SetValue(tw.Player,"1000"),"Team input retains full original round range");Check(Field<TeamSettings>(teams,"settings").FallbackMaxRounds==1000&&Field<TeamSettings>(teams,"settings").BlockAtMaxRoundsPercent==.37,"Team input preserves custom fractional threshold");
Check(File.ReadAllText(selectionPath)==selectionBefore,"Selections and administrator ownership untouched");teams.AdminCommand(tw.Context);await Choose(tw,"Verliererteam (7)");await Choose(tw,"Alle Spieler");int seen=0;do{seen+=tw.Labels.Count(x=>x.Contains("Offline"));if(!tw.Labels.Any(x=>x.Contains("Nächste")))break;await tw.Click("Nächste");}while(true);Check(seen==7,"All offline selections reachable through compact pages");
var cw=World("chat");var json=new JsonSerializerOptions{WriteIndented=true,PropertyNamingPolicy=JsonNamingPolicy.SnakeCaseLower,DefaultIgnoreCondition=JsonIgnoreCondition.WhenWritingNull};var cfg=AntiAdConfig.CreateDefault();cfg.GagAtViolation=81;cfg.KickAtViolation=95;cfg.RepeatWindowMinutes=1301;cfg.GagMinutes=1401;cfg.ElevatedRoleWarningCooldownSeconds=271;string cp=Path.Combine(cw.DataDirectory,"config.json");File.WriteAllText(cp,JsonSerializer.Serialize(cfg,json));
string gp=Path.Combine(cw.DataDirectory,"global_protection.json");File.WriteAllText(gp,JsonSerializer.Serialize(new GlobalProtectionSnapshot{Domains=["global.example"]},json));string globalBefore=File.ReadAllText(gp);
var chat=new LPLK_ChatGuard.Plugin(cw.Core);chat.Load(true);chat.Command(cw.Context);var gags=Field<Dictionary<ulong,DateTimeOffset>>(chat,"_gagUntil");gags[42]=DateTimeOffset.UtcNow.AddMinutes(30);var violations=Field<Dictionary<ulong,ViolationState>>(chat,"_violations");violations[42]=new(){Count=2,FirstAt=DateTimeOffset.UtcNow,LastAt=DateTimeOffset.UtcNow};
cfg.CheckPlayerNames=false;cfg.GagMinutes=1440;File.WriteAllText(cp,JsonSerializer.Serialize(cfg,json));await Choose(cw,"Namen prüfen: True");Check(Field<AntiAdConfig>(chat,"_config") is {CheckPlayerNames:true,GagMinutes:1440,GagAtViolation:81},"Chat toggle merges latest snake_case config without losing custom ranges");Check(gags.ContainsKey(42)&&violations[42].Count==2,"Configuration edit preserves sanctions already accumulated");
File.WriteAllText(cp,"{\"gag_minutes\":0}");await Choose(cw,"Rollenschutz: True");Check(Field<AntiAdConfig>(chat,"_config").HardActionsOnlyForPlayerRole&&File.ReadAllText(cp).Contains(":0"),"Invalid ChatGuard config blocks menu write");
File.WriteAllText(cp,JsonSerializer.Serialize(cfg,json));Refresh(chat);await Choose(cw,"Gagschwelle: 81");var input=(InputMenuOption)cw.Current!.Options[0];
Check(!input.SetValue(cw.Player,"101")&&!input.SetValue(cw.Player,"NaN"),"Numeric input rejects invalid full-range value");Check(input.SetValue(cw.Player,"100"),"Input accepts original upper limit");Check(Field<AntiAdConfig>(chat,"_config").GagAtViolation==100,"Real input callback saves full valid upper limit");
await Choose(cw,"Gagdauer: 1440 min");Check(((InputMenuOption)cw.Current!.Options[0]).SetValue(cw.Player,"1"),"Minimum duration accepted");Check(Field<AntiAdConfig>(chat,"_config").GagMinutes==1,"Full duration range saved");await Choose(cw,"Warnabstand: 271s");Check(((InputMenuOption)cw.Current!.Options[0]).SetValue(cw.Player,"300"),"Full role-warning interval accepted");await Choose(cw,"Sperrdomains (6)");await Choose(cw,"Entfernen: cs2commends · com");await Choose(cw,"Entfernen bestätigen");Check(!Field<AntiAdConfig>(chat,"_config").BlockedDomains.Contains("cs2commends.com"),"Paged list delete confirmation persists");Check(File.ReadAllText(gp)==globalBefore,"Global rules preserved byte for byte");
foreach(var item in new (object Plugin,MenuWorld World,string File,string Bad,string Good)[]{(teams,tw,tp,"{\"Unknown\":1}",JsonSerializer.Serialize(ts)),(chat,cw,cp,"{\"unknown\":1}",JsonSerializer.Serialize(cfg,json))}){
 foreach(string bad in new[]{item.Bad,"null","[]",item.Plugin==teams?new string(' ',65537):new string(' ',SettingsStore.MaxBytes+1)}){File.WriteAllText(item.File,bad);Refresh(item.Plugin);Check(item.Plugin==teams?Field<string?>(item.Plugin,"reloadError") is not null:Field<string?>(item.Plugin,"_configError") is not null,"Invalid config remains visibly rejected");}
 File.WriteAllText(item.File,item.Good);Refresh(item.Plugin);Check(item.Plugin==teams?Field<string?>(item.Plugin,"reloadError") is null:Field<string?>(item.Plugin,"_configError") is null,"Corrected config recovers");
 string status=Path.Combine(item.World.DataDirectory,"status.json");File.Delete(status);Directory.CreateDirectory(status);Refresh(item.Plugin);Check(Directory.Exists(status),"Read-only status destination cannot break rules");Directory.Delete(status);Refresh(item.Plugin);Check(File.Exists(status),"Status writes recover");
 foreach(var menu in item.World.AllMenus){Check(menu.Configuration.MaxVisibleItems==5,"At most five menu rows");foreach(var back in menu.Options.Where(x=>x.Text.Contains("Zurück")))Check(!System.Text.RegularExpressions.Regex.IsMatch(back.Text,@"\d+[.)]"),"Back unnumbered");}
}
