var large=AntiAdConfig.CreateDefault();large.BlockedDomains=Enumerable.Repeat(new string('ä',200),256).ToList();large.AllowedDomains=[..large.BlockedDomains];large.MarketingKeywords=[..large.BlockedDomains];File.WriteAllText(cp,JsonSerializer.Serialize(large,json));var store=new SettingsStore(cp,json);Check(new FileInfo(cp).Length>65536&&store.Current.MarketingKeywords.Count==256,"All maximal legacy lists accepted");string before=File.ReadAllText(cp);try{store.Change(c=>c.BlockedDomains.Add("overflow.example"));throw new Exception("Expected rejected list overflow");}catch(InvalidDataException){}Check(store.Current.BlockedDomains.Count==256&&File.ReadAllText(cp)==before,"Rejected mutable-list edit cannot mutate current rules");
try{store.Change(c=>{c.Enabled=false;File.WriteAllText(cp,JsonSerializer.Serialize(cfg,json));});throw new Exception("Expected write conflict");}catch(IOException){}Check(File.ReadAllText(cp)==JsonSerializer.Serialize(cfg,json),"Edit-time external change is not overwritten");
