teams.Unload();chat.Unload();Check(gags.Count==0&&violations.Count==0,"Unload retains established cleanup lifecycle");Console.WriteLine($"AdministrationMaintenanceChecks: {checks} checks passed; real menu callbacks, config files and retained moderation data; no native player actions.");
